    def test_brainpoolP256r1_sha3_256(
        self, name: str, pk: bytes, msg: bytes, sig: bytes, expected: bool
    ):
        decoder = SEC1Encoder()
        public_key = decoder.decode_public_key(pk, brainpoolP256r1)

        try:
            signature = DEREncoder.decode_signature(sig)
            result = verify(signature, msg, public_key, brainpoolP256r1, sha3_256)
            self.assertEqual(result, expected, name)
        except Exception:
            self.assertFalse(expected, name)
